import {readBoundedJson,RequestBodyError} from '../_shared/request-budget.mjs';
// Server-only, allowlisted official product verification.
// The browser cannot supply verification evidence or write canonical records.
// Supabase JWT gateway verification must stay ENABLED.
import {createClient} from 'npm:@supabase/supabase-js@2.117.3';
import {extractOfficialEvidence,officialProductUrl} from './evidence.mjs';

const allowOrigins=new Set([
 'https://app.dialincollective.com',
 'https://the-dial-in-collective.netlify.app',
 'http://localhost:5173',
 'http://localhost:8888',
]);
const json=(data,status=200,origin='')=>new Response(JSON.stringify(data),{
 status,headers:{
  'Content-Type':'application/json;charset=utf-8','Cache-Control':'no-store',
  ...(allowOrigins.has(origin)?{'Access-Control-Allow-Origin':origin,'Vary':'Origin'}:{})
 }
});
async function readSmallHtml(url){
 const reply=await fetch(url,{
  redirect:'manual',
  signal:AbortSignal.timeout(10000),
  headers:{'Accept':'text/html,application/xhtml+xml','User-Agent':'DialInCollective-OfficialProductVerifier/1.0'}
 });
 if(reply.status>=300&&reply.status<400)return {ok:false,reason:'redirect_requires_review'};
 if(!reply.ok)return {ok:false,reason:'source_unavailable'};
 const type=(reply.headers.get('content-type')||'').toLowerCase();
 if(!type.includes('text/html')&&!type.includes('application/xhtml+xml'))return {ok:false,reason:'not_html'};
 const announced=Number(reply.headers.get('content-length')||0);
 if(announced>950000)return {ok:false,reason:'page_too_large'};
 const reader=reply.body?.getReader();
 if(!reader)return {ok:false,reason:'source_unavailable'};
 const decoder=new TextDecoder(),fragments=[];let bytes=0;
 try{
  while(true){
   const {done,value}=await reader.read();
   if(done)break;
   bytes+=value?.byteLength||0;
   if(bytes>950000){await reader.cancel();return {ok:false,reason:'page_too_large'};}
   fragments.push(decoder.decode(value,{stream:true}));
  }
  fragments.push(decoder.decode());
  return {ok:true,html:fragments.join('')};
 }finally{reader.releaseLock();}
}
Deno.serve(async req=>{
 const origin=req.headers.get('origin')||'';
 if(origin&&!allowOrigins.has(origin))return json({ok:false,reason:'origin_not_allowed'},403,'');
 if(req.method==='OPTIONS')return new Response(null,{status:204,headers:{
  'Access-Control-Allow-Origin':allowOrigins.has(origin)?origin:'null',
  'Access-Control-Allow-Headers':'authorization,apikey,x-client-info,content-type',
  'Access-Control-Allow-Methods':'POST,OPTIONS',
  'Access-Control-Max-Age':'3600','Vary':'Origin'
 }});
 if(req.method!=='POST')return json({ok:false,reason:'method_not_allowed'},405,origin);
 const auth=req.headers.get('authorization')||'';
 const token=auth.startsWith('Bearer ')?auth.slice(7):'';
 if(!token)return json({ok:false,reason:'sign_in_required'},401,origin);
 const base=Deno.env.get('SUPABASE_URL'),anon=Deno.env.get('SUPABASE_ANON_KEY'),
       secret=Deno.env.get('SUPABASE_SERVICE_ROLE_KEY');
 if(!base||!anon||!secret)return json({ok:false,reason:'verification_not_configured'},503,origin);
 try{
  const payload=await readBoundedJson(req);
  const sid=payload?.submission_id;
  if(typeof sid!=='string'||!/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(sid))
   return json({ok:false,reason:'invalid_submission'},400,origin);
  const userClient=createClient(base,anon,{auth:{persistSession:false,autoRefreshToken:false},
   global:{headers:{Authorization:'Bearer '+token}}});
  const {data:userResult,error:userError}=await userClient.auth.getUser(token);
  if(userError||!userResult?.user?.id)return json({ok:false,reason:'sign_in_required'},401,origin);
  // A still-valid login token is not beta membership. Verify current access
  // before any service-role read, fetch budget claim, or catalog promotion.
  const {data:status,error:statusError}=await userClient.rpc('dic_session_status');
  if(statusError||status?.admitted!==true)return json({ok:false,reason:'admitted_member_required'},403,origin);
  const privileged=createClient(base,secret,{auth:{persistSession:false,autoRefreshToken:false}});
  const {data:row,error:readError}=await privileged.from('coffee_submissions')
   .select('id,owner_id,status,canonical_coffee_id').eq('id',sid).maybeSingle();
  if(readError)return json({ok:false,reason:'verification_unavailable'},503,origin);
  if(!row||row.owner_id!==userResult.user.id)return json({ok:false,reason:'submission_not_accessible'},403,origin);
  if(row.status==='approved'||row.status==='merged')
   // Canonical catalog approval can be manual/member approval. It does not
   // establish official product evidence in this request.
   return json({ok:true,status:'verified',source_verified:false,coffee_id:row.canonical_coffee_id},200,origin);
  if(!['pending','conflict'].includes(row.status))return json({ok:false,status:'pending',reason:'not_eligible'},200,origin);
  const {data:target,error:targetError}=await privileged.rpc('dic_source_check_target',{submission_id:sid});
  if(targetError||!target?.official_host)return json({ok:false,status:'pending',reason:'no_verified_roaster_source'},200,origin);
  const link=officialProductUrl(target.source_url,target.official_host);
  if(!link)return json({ok:false,status:'pending',reason:'untrusted_source_url'},200,origin);
  const {data:claim,error:claimError}=await privileged.rpc('dic_source_claim',{submission_id:sid});
  if(claimError||claim?.allowed!==true)return json({ok:false,status:'pending',reason:claim?.reason||'rate_limited'},200,origin);
  let page;
  try{page=await readSmallHtml(link);}catch{return json({ok:false,status:'pending',reason:'source_fetch_failed'},200,origin);}
  if(!page.ok)return json({ok:false,status:'pending',reason:page.reason},200,origin);
  const inspected=extractOfficialEvidence(page.html,{...target,source_url:link});
  if(!inspected.ok)return json({ok:false,status:'pending',reason:inspected.reason},200,origin);
  const evidence={
   ...inspected,checked_url:link,submission_revision:target.submission_revision,
   // Supabase checks the exact current submission URL and roaster domain again.
   official_page_confirmed:true
  };
  const {data:promoted,error:promoteError}=await privileged.rpc('dic_trusted_source_verify',
   {submission_id:sid,evidence});
  if(promoteError)return json({ok:false,status:'pending',reason:'verification_requires_review'},200,origin);
  if(!promoted?.ok)return json({ok:false,status:'pending',reason:promoted?.code||'needs_confirmation'},200,origin);
  return json({ok:true,status:'verified',source_verified:promoted.already_verified!==true,coffee_id:promoted.coffee_id,canonical_name:promoted.canonical_name},200,origin);
 }catch(error){
  if(error instanceof RequestBodyError)return json({ok:false,reason:error.code},error.status,origin);
  return json({ok:false,status:'pending',reason:'verification_failed'},200,origin);
 }
});

// Shared Node/Deno body budget. No unbounded req.json(), timers or SDK calls.
export class RequestBodyError extends Error {
 constructor(code,status=400){super(code);this.name='RequestBodyError';this.code=code;this.status=status;}
}
export async function readBoundedJson(request,{maxBytes=4200,timeoutMs=5000}={}){
 if(!Number.isSafeInteger(maxBytes)||maxBytes<1||!Number.isFinite(timeoutMs)||timeoutMs<1)
  throw new TypeError('Invalid request budget');
 if((request.headers.get('content-type')||'').split(';')[0].trim().toLowerCase()!=='application/json')
  throw new RequestBodyError('invalid_content_type',415);
 const announced=request.headers.get('content-length');
 if(announced!==null&&(!/^[0-9]+$/.test(announced)||Number(announced)>maxBytes))
  throw new RequestBodyError('request_too_large',413);
 if(request.signal?.aborted)throw new RequestBodyError('request_aborted',400);
 const reader=request.body?.getReader();if(!reader)throw new RequestBodyError('missing_request');
 let timer,abort,finished=false;
 const cancel=()=>{try{Promise.resolve(reader.cancel()).catch(()=>{});}catch{/* Never wait on an untrusted cancel hook. */}};
 try{
  const expired=new Promise((_,reject)=>{
   timer=setTimeout(()=>{cancel();reject(new RequestBodyError('request_timeout',408));},timeoutMs);
   abort=()=>{cancel();reject(new RequestBodyError('request_aborted',400));};
   request.signal?.addEventListener('abort',abort,{once:true});
   if(request.signal?.aborted)abort();
  });
  const read=async()=>{
   const decoder=new TextDecoder('utf-8',{fatal:true}),chunks=[];let size=0;
   while(true){const {done,value}=await reader.read();if(done)break;
    size+=value.byteLength;if(size>maxBytes)throw new RequestBodyError('request_too_large',413);
    chunks.push(decoder.decode(value,{stream:true}));
   }
   chunks.push(decoder.decode());
   let data;try{data=JSON.parse(chunks.join(''));}catch{throw new RequestBodyError('invalid_json');}
   if(!data||typeof data!=='object'||Array.isArray(data))throw new RequestBodyError('invalid_json');
   finished=true;return data;
  };
  return await Promise.race([read(),expired]);
 }catch(error){
  if(error instanceof RequestBodyError)throw error;
  throw new RequestBodyError('invalid_json');
 }finally{
  clearTimeout(timer);if(abort)request.signal?.removeEventListener('abort',abort);
  if(!finished)cancel();
  try{reader.releaseLock();}catch{/* A cancelled pending read may settle asynchronously. */}
 }
}

import {rawElements,removeElements} from '../_shared/html-scan.mjs';
import {isRecurringCoffeeHarvestWindow,isGenericCoffeeLotLabel} from '../_shared/coffee-release-label.mjs';
// Deterministic official-product evidence parser. No AI calls, no HTML execution.
// This file is shared by Deno Edge and the Node regression suite.
export function normalizeWords(value) {
 return String(value??'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'')
  .toLowerCase().replace(/&/g,' and ').replace(/[^a-z0-9]+/g,' ').trim().replace(/\s+/g,' ');
}
function decodeHtml(value) {
 return String(value??'').replace(/&#(?:x([0-9a-f]+)|([0-9]+));/gi,(_m,h,d)=>{
  const code=Number.parseInt(h||d,h?16:10);
  return code>0&&code<=0x10ffff?String.fromCodePoint(code):'';
 }).replace(/&(?:amp|quot|apos|lt|gt|nbsp);/gi,v=>({
  '&amp;':'&','&quot;':'"','&apos;':"'",'&lt;':'<','&gt;':'>','&nbsp;':' '
 })[v.toLowerCase()]||v);
}
export function officialProductUrl(raw,registeredDomain) {
 if(typeof raw!=='string'||raw.length>4000||!registeredDomain||!/^[a-z0-9-]+(?:\.[a-z0-9-]+)+$/.test(registeredDomain))return null;
 try {
  const u=new URL(raw);
  if(u.protocol!=='https:'||u.username||u.password||u.port||u.hash||!['',null].includes(u.hash))return null;
  if(![registeredDomain,'www.'+registeredDomain].includes(u.hostname.toLowerCase()))return null;
  if(!/^\/(?:products|product)\/[a-z0-9][a-z0-9._~%+-]*(?:\/)?$/i.test(u.pathname))return null;
  if(u.search.length>600)return null;
  for(const [key,value] of u.searchParams){
   const lower=key.toLowerCase();
   if(!(lower==='variant'||lower==='srsltid'||lower==='gclid'||lower==='fbclid'||
       lower==='msclkid'||/^utm_[a-z0-9_]{1,60}$/.test(lower))||value.length>200)return null;
  }
  return u.toString();
 } catch {return null;}
}
function walkProduct(data,products,limit=0) {
 if(limit>8||!data||typeof data!=='object')return;
 if(Array.isArray(data)){for(const d of data.slice(0,30))walkProduct(d,products,limit+1);return;}
 const types=Array.isArray(data['@type'])?data['@type']:[data['@type']];
 if(types.some(t=>String(t||'').toLowerCase()==='product')&&typeof data.name==='string')
  products.push({name:decodeHtml(data.name),description:decodeHtml(data.description||''),url:typeof data.url==='string'?data.url:null,kind:'jsonld_product',attributes:data.additionalProperty});
 if(Array.isArray(data['@graph']))walkProduct(data['@graph'],products,limit+1);
}
function metas(html) {
 const out={};
 for(const tag of html.match(/<meta\b[^<>]{0,1800}>/gi)||[]){
  const attributes={};
  for(const x of tag.matchAll(/(?:^|[\s<])([a-z-]{1,64})\s*=\s*(?:"([^"]{0,2000})"|'([^']{0,2000})')/gi))
   attributes[x[1].toLowerCase()]=decodeHtml(x[2]??x[3]);
  const key=(attributes.property||attributes.name||'').toLowerCase();
  if(key==='og:title'||key==='og:type'||key==='description')out[key]=attributes.content||'';
 }
 return out;
}
function uniqueProductHeading(html,sourceUrl,meta){
 // Metadata-poor roasters often publish an obvious product H1 but omit JSON-LD.
 // Use H1 ONLY for an already trusted, exact-host official /products/{slug}
 // source verified by the calling worker (not for arbitrary scraped webpages).
 try{
  const url=new URL(sourceUrl);
  if(!/^\/(?:products|product)\/[a-z0-9][a-z0-9._~%+-]*\/?$/i.test(url.pathname))return null;
 }catch{return null;}
 const headings=[...html.matchAll(/<h1\b[^<>]{0,400}>([\s\S]{0,320}?)<\/h1>/gi)]
  .map(x=>({index:x.index,name:decodeHtml(x[1].replace(/<[^<>]{0,2000}>/g,' ')).replace(/\s+/g,' ').trim()}))
  .filter(x=>x.name&&!/^(shop|products?|coffees?|search|home|menu)$/i.test(x.name));
 if(headings.length!==1)return null;
 const heading=headings[0];
 const local=html.slice(heading.index,heading.index+4800);
 const bounded=local.split(/<footer\b|<h[2-4]\b[^<>]{0,2000}>\s*(?:more coffees|related products|you may also like)/i)[0];
 const description=decodeHtml(removeElements(bounded,['script','style'])
  .replace(/<[^<>]{0,2000}>/g,' ').replace(/\s+/g,' ')).slice(0,1000);
 return {name:heading.name,description:description||meta.description||'',url:sourceUrl,
  kind:'official_product_page',attributes:null};
}
function explicitReleaseYears(product){
 const years=new Set(normalizeWords(product.name).match(/\b(?:19|20)\d\d\b/g)||[]);
 // Keep sentence punctuation: "our company started in 2025. Harvest 2024"
 // must not turn a nearby unrelated year into release evidence.
 const description=String(product.description||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'')
  .toLowerCase().replace(/<[^<>]{0,2000}>/g,' ').slice(0,1000);
 const date='(?:19|20)\\d\\d(?:\\s*[/–—-]\\s*(?:(?:19|20)?\\d\\d))?';
 const label='(?:harvest|crop|release|season|selection)';
 const before=new RegExp('\\b'+label+'(?:\\s+year)?(?:\\s+(?:for|of|in|from))?\\s*[:–—-]?\\s*('+date+')\\b','g');
 const after=new RegExp('\\b('+date+')\\s+'+label+'\\b','g');
 for(const pattern of [before,after]){
  for(const match of description.matchAll(pattern)){
   const parts=match[1].match(/\d+/g)||[];
   for(const part of parts)years.add(part.length===2?parts[0].slice(0,2)+part:part);
  }
 }
 return [...years];
}
function hasReleaseProof(entered,product){
 if(!entered)return true;
 // "January" and "July–September" can match the official page every year.
 // They are harvest guidance, not corroboration of a particular release.
 if(isRecurringCoffeeHarvestWindow(entered)||isGenericCoffeeLotLabel(entered))return false;
 const value=normalizeWords(entered);
 const snippet=normalizeWords(product.name+' '+product.description.slice(0,1000));
 if(!value)return false;
 const fullLabel=(' '+snippet+' ').includes(' '+value+' ');
 const words=value.split(' '),year=/^(?:19|20)\d\d$/;
 const years=words.filter(word=>year.test(word));
 // A year may establish a plain harvest label, but never an unproved lot,
 // batch, or named release that happens to share that year. Such labels
 // require the full identity above; ambiguous evidence stays Pending.
 const plainHarvest=words.every(word=>year.test(word)||/^(?:harvest|crop|release|season|year)$/.test(word));
 const provedYears=explicitReleaseYears(product);
 // A bare year is proof only in the product title or explicit harvest/crop/
 // release/selection text. Conflicting release years never auto-promote.
 if(years.length&&provedYears.some(y=>!years.includes(y)))return false;
 if(plainHarvest)return years.length>0&&years.every(y=>provedYears.includes(y));
 // Lot, batch and named releases require the complete literal label.
