    score<(resolvedScale==='commercial'?75.4:100)){
  const midpoints=anchorScores.slice(0,-1).map((x,i)=>(x+anchorScores[i+1])/2);
  const index=midpoints.findIndex(midpoint=>score>=midpoint);
